  "dependencies": { "express": "5.1.0" }
}

import express from 'express';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';

const app = express();
app.use(express.json());

const port = Number(process.env.PORT ?? 80);
const dataDir = process.env.DATA_DIR ?? '/app/data';
const file = `${dataDir}/notes.json`;
const load = () => (existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : []);

app.get('/health', (_req, res) => res.type('text').send('ok'));
app.get('/notes', (_req, res) => res.json(load()));
app.post('/notes', (req, res) => {
  const notes = load();
  notes.push({ text: String(req.body?.text ?? '') });
  mkdirSync(dataDir, { recursive: true });
  writeFileSync(file, JSON.stringify(notes));
  res.status(201).json(notes.at(-1));
});

app.listen(port, () => console.log(`notes-api listening on ${port}`));

import json
import os
import pathlib

from flask import Flask, jsonify, request

if not os.environ.get("DB_PASSWORD"):
    raise SystemExit("DB_PASSWORD is required")

DATA = pathlib.Path(os.environ.get("DATA_DIR", "/var/lib/notes")) / "notes.json"
app = Flask(__name__)


def load():
    return json.loads(DATA.read_text()) if DATA.exists() else []


@app.get("/health")
def health():
    return "ok"


@app.route("/notes", methods=["GET", "POST"])
def notes():
    items = load()
    if request.method == "POST":
        items.append({"text": str((request.get_json(silent=True) or {}).get("text", ""))})
        DATA.parent.mkdir(parents=True, exist_ok=True)
        DATA.write_text(json.dumps(items))
    return jsonify(items)
